#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ErrorKind {
    InvalidInput,
    Io,
    Sqlite,
    Schema,
    LedgerMissing,
    Redaction,
    NotFound,
    TenantMismatch,
    ConnectorBlocked,
    VerifierFailed,
    HashChain,
}

#[derive(Debug)]
pub struct BlackboxError {
    kind: ErrorKind,
    error_code: &'static str,
    message: String,
    source_of_truth: Option<String>,
    field_path: Option<String>,
    remediation: String,
    connector: &'static str,
}

impl BlackboxError {
    fn new(
        kind: ErrorKind,
        error_code: &'static str,
        message: impl Into<String>,
        source_of_truth: Option<String>,
        field_path: Option<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self::new_with_connector(
            kind,
            error_code,
            message,
            source_of_truth,
            SQLITE_CONNECTOR_ID,
            field_path,
            remediation,
        )
    }

    fn new_with_connector(
        kind: ErrorKind,
        error_code: &'static str,
        message: impl Into<String>,
        source_of_truth: Option<String>,
        connector: &'static str,
        field_path: Option<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self {
            kind,
            error_code,
            message: message.into(),
            source_of_truth,
            field_path,
            remediation: remediation.into(),
            connector,
        }
    }

    fn invalid(message: impl Into<String>, remediation: impl Into<String>) -> Self {
        Self::new(
            ErrorKind::InvalidInput,
            "BBX_INVALID_INPUT",
            message,
            None,
            None,
            remediation,
        )
    }

    fn invalid_field_for_ledger(
        path: &Path,
        field_path: impl Into<String>,
        message: impl Into<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self::new(
            ErrorKind::InvalidInput,
            "BBX_INVALID_INPUT",
            message,
            Some(source_of_truth(path)),
            Some(field_path.into()),
            remediation,
        )
    }

    fn io(path: &Path, action: &'static str, err: std::io::Error) -> Self {
        Self::new(
            ErrorKind::Io,
            "BBX_IO_ERROR",
            format!("{action}: {err}"),
            Some(source_of_truth(path)),
            None,
            "check the path, parent directory, and filesystem permissions",
        )
    }

    fn sqlite(path: &Path, action: &'static str, err: rusqlite::Error) -> Self {
        Self::new(
            ErrorKind::Sqlite,
            "BBX_SQLITE_ERROR",
            format!("{action}: {err}"),
            Some(source_of_truth(path)),
            None,
            "inspect the SQLite error, verify the ledger path, and rerun after fixing the database state",
        )
    }

    fn schema(path: &Path, message: impl Into<String>) -> Self {
        Self::schema_field(path, "schema", message)
    }

    fn schema_field(
        path: &Path,
        field_path: impl Into<String>,
        message: impl Into<String>,
    ) -> Self {
        Self::new(
            ErrorKind::Schema,
            "BBX_SCHEMA_VALIDATION_FAILED",
            message,
            Some(source_of_truth(path)),
            Some(field_path.into()),
            "run `blackbox init --ledger PATH` against a new ledger or migrate the existing database explicitly",
        )
    }

    fn ledger_missing(path: &Path) -> Self {
        Self::new(
            ErrorKind::LedgerMissing,
            "BBX_LEDGER_NOT_INITIALIZED",
            format!("ledger is not initialized at {}", path.display()),
            Some(source_of_truth(path)),
            Some("--ledger".to_string()),
            "initialize the physical ledger first with `blackbox init --ledger PATH`",
        )
    }

    fn redaction(path: &Path, field_path: String, message: impl Into<String>) -> Self {
        Self::new(
            ErrorKind::Redaction,
            "BBX_REDACTION_VIOLATION",
            message,
            Some(source_of_truth(path)),
            Some(field_path),
            "move the sensitive value into an explicitly redacted field or remove it before recording",
        )
    }

    fn not_found(path: &Path, message: impl Into<String>) -> Self {
        Self::new(
            ErrorKind::NotFound,
            "BBX_RECORD_NOT_FOUND",
            message,
            Some(source_of_truth(path)),
            Some("--run-id".to_string()),
            "record the parent run first and retry with an existing run_id",
        )
    }

    fn tenant_mismatch(path: &Path, run_id: &str, expected: &str, actual: &str) -> Self {
        Self::new(
            ErrorKind::TenantMismatch,
            "BBX_TENANT_MISMATCH",
            format!(
                "run_id {run_id} belongs to tenant {expected}, but the tool-call was recorded for tenant {actual}"
            ),
            Some(source_of_truth(path)),
            Some("ledger_records.tenant_id".to_string()),
            "record the tool call with the parent run's tenant_id or start a new run for the requested tenant",
        )
    }

    fn hash_chain(path: &Path, field_path: String, message: impl Into<String>) -> Self {
        Self::new(
            ErrorKind::HashChain,
            "BBX_HASH_CHAIN_BROKEN",
            message,
            Some(source_of_truth(path)),
            Some(field_path),
            "treat the ledger as tampered or corrupt; restore from trusted backup or start a new ledger",
        )
    }

    fn evidence_integrity(
        error_code: &'static str,
        source_of_truth: String,
        field_path: impl Into<String>,
        message: impl Into<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self::evidence_integrity_for_connector(
            error_code,
            SQLITE_CONNECTOR_ID,
            source_of_truth,
            field_path,
            message,
            remediation,
        )
    }

    fn evidence_integrity_for_connector(
        error_code: &'static str,
        connector: &'static str,
        source_of_truth: String,
        field_path: impl Into<String>,
        message: impl Into<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self::new_with_connector(
            ErrorKind::HashChain,
            error_code,
            message,
            Some(source_of_truth),
            connector,
            Some(field_path.into()),
            remediation,
        )
    }

    fn verifier_spec(
        path: &Path,
        field_path: impl Into<String>,
        message: impl Into<String>,
    ) -> Self {
        Self::new(
            ErrorKind::InvalidInput,
            "BBX_VERIFIER_SPEC_INVALID",
            message,
            Some(source_of_truth(path)),
            Some(field_path.into()),
            "fix the verifier spec JSON so required fields and types match the verifier contract",
        )
    }

    fn connector_blocked(
        error_code: &'static str,
        connector: &'static str,
        source_of_truth: String,
        field_path: impl Into<String>,
        message: impl Into<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self::new_with_connector(
            ErrorKind::ConnectorBlocked,
            error_code,
            message,
            Some(source_of_truth),
            connector,
            Some(field_path.into()),
            remediation,
        )
    }

    fn verifier_failed(
        error_code: &'static str,
        connector: &'static str,
        source_of_truth: String,
        field_path: impl Into<String>,
        message: impl Into<String>,
        remediation: impl Into<String>,
    ) -> Self {
        Self::new_with_connector(
            ErrorKind::VerifierFailed,
            error_code,
            message,
            Some(source_of_truth),
            connector,
            Some(field_path.into()),
            remediation,
        )
    }

    fn exit_code(&self) -> i32 {
        match self.kind {
            ErrorKind::HashChain => 2,
            _ => 1,
        }
    }

    fn to_json(&self) -> Value {
        json!({
            "status": "error",
            "error_code": self.error_code,
            "message": self.message,
            "source_of_truth": self.source_of_truth,
            "connector": self.connector,
            "field_path": self.field_path,
            "remediation": self.remediation,
        })
    }
}

impl std::fmt::Display for BlackboxError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.error_code, self.message)
    }
}

impl std::error::Error for BlackboxError {}

type BbxResult<T> = Result<T, BlackboxError>;

pub async fn handle_blackbox_command(command: BlackboxCommands) -> i32 {
    match command {
        BlackboxCommands::Mcp { action } => return handle_mcp_command(action).await,
        BlackboxCommands::Server { action } => return handle_server_command(action).await,
        other => return handle_blackbox_json_command(other).await,
    }
}

async fn handle_blackbox_json_command(command: BlackboxCommands) -> i32 {
    match run_blackbox_command(command).await {
        Ok(output) => {
            println!(
                "{}",
                serde_json::to_string_pretty(&output).expect("JSON output serializes")
            );
            0
        }
        Err(err) => {
            eprintln!(
                "{}",
                serde_json::to_string_pretty(&err.to_json()).expect("JSON error serializes")
            );
            err.exit_code()
        }
    }
}

async fn run_blackbox_command(command: BlackboxCommands) -> BbxResult<Value> {
    match command {
        BlackboxCommands::Init(args) => init_ledger(args),
        BlackboxCommands::Connector { action } => match action {
            ConnectorCommands::List => connector_list(),
            ConnectorCommands::Test(args) => connector_test(args).await,
        },
        BlackboxCommands::Record { action } => match action {
            RecordCommands::Run(args) => record_run(args),
            RecordCommands::Step(args) => record_agent_step(args),
            RecordCommands::ModelDecision(args) => record_model_decision(args),
            RecordCommands::ToolCall(args) => record_tool_call(args),
        },
        BlackboxCommands::Sdk { action } => match action {
            SdkCommands::Schema(args) => sdk_schema(args),
            SdkCommands::Ingest(args) => sdk_ingest(args),
        },
        BlackboxCommands::Policy { action } => match action {
            PolicyCommands::Evaluate(args) => policy_evaluate(args),
            PolicyCommands::Registry(args) => policy_registry(args),
        },
        BlackboxCommands::Mcp { action: _ } => Err(BlackboxError::invalid(
            "MCP server commands must be handled through the stdio server path",
            "report this as a bug; handle_blackbox_command should intercept MCP commands",
        )),
        BlackboxCommands::Api { action } => match action {
            ApiCommands::Surface(args) => api_surface(args),
        },
        BlackboxCommands::Server { action: _ } => Err(BlackboxError::invalid(
            "HTTP server commands must be handled through the server path",
            "report this as a bug; handle_blackbox_command should intercept server commands",
        )),
        BlackboxCommands::Verify(args) => verify_local(args).await,
        BlackboxCommands::Replay(args) => replay_run(args),
        BlackboxCommands::Export { action } => match action {
            ExportCommands::Evidence(args) => export_evidence(args),
            ExportCommands::Episodes(args) => export_episodes(args),
            ExportCommands::Otel(args) => export_otel(args),
        },
        BlackboxCommands::Dashboard { action } => match action {
            DashboardCommands::Build(args) => dashboard_build(args),
            DashboardCommands::Api(args) => dashboard_api(args),
        },
        BlackboxCommands::Enterprise { action } => match action {
            EnterpriseCommands::Configure(args) => enterprise_configure(args),
            EnterpriseCommands::SyncDirectory(args) => enterprise_sync_directory(args),
            EnterpriseCommands::AccessEvaluate(args) => enterprise_access_evaluate(args),
            EnterpriseCommands::ExportAudit(args) => enterprise_export_audit(args),
        },
        BlackboxCommands::Score { action } => match action {
            ScoreCommands::Run(args) => score_run(args),
        },
        BlackboxCommands::Privacy { action } => match action {
            PrivacyCommands::EvaluateRetention(args) => privacy_evaluate_retention(args),
            PrivacyCommands::RequestErasure(args) => privacy_request_erasure(args),
        },
        BlackboxCommands::Gate { action } => match action {
            GateCommands::Evaluate(args) => gate_evaluate(args),
        },
        BlackboxCommands::Package { action } => match action {
            PackageCommands::PilotReport(args) => package_pilot_report(args),
        },
        BlackboxCommands::Risk { action } => match action {
            RiskCommands::Evaluate(args) => risk_evaluate(args),
        },
        BlackboxCommands::Reward { action } => match action {
            RewardCommands::Compile(args) => reward_compile(args),
        },
        BlackboxCommands::Demo { action } => match action {
            DemoCommands::FirstWedge(args) => demo_first_wedge(args),
        },
        BlackboxCommands::Fsv { action } => match action {
            FsvCommands::Certify(args) => fsv_certify(args),
        },
        BlackboxCommands::Inspect { action } => match action {
            InspectCommands::Ledger(args) => inspect_ledger(args),
        },
    }
}

async fn handle_server_command(action: ServerCommands) -> i32 {
    let result = match action {
        ServerCommands::Serve(args) => serve_http(args).await,
    };
    match result {
        Ok(()) => 0,
        Err(err) => {
            eprintln!(
                "{}",
                serde_json::to_string_pretty(&err.to_json()).expect("JSON error serializes")
            );
            err.exit_code()
        }
    }
}

#[derive(Clone)]
struct HttpServerState {
    ledger: PathBuf,
    api_key_sha256: String,
    write_lock: Arc<tokio::sync::Mutex<()>>,
    bind: SocketAddr,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct HttpRecordRunRequest {
    tenant: String,
    task: String,
    agent: String,
    model: Option<String>,
    task_kind: String,
    risk_tier: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct HttpRecordStepRequest {
    tenant: String,
    summary: String,
    step_kind: String,
    agent: String,
    model: Option<String>,
    context: Option<Value>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct HttpRecordToolCallRequest {
    tenant: String,
    run_id: String,
    tool: String,
    input: Value,
    agent: String,
    model: Option<String>,
    capability: String,
    status: String,
    external_request_id: Option<String>,
}

struct HttpRequestContext {
    request_id: String,
    tenant: String,
}

struct HttpAuditInput<'a> {
    request_id: &'a str,
    tenant: &'a str,
    method: &'a str,
    path: &'a str,
    route_id: &'a str,
    status_code: u16,
    outcome: &'a str,
    error_code: Option<&'a str>,
    request_body_sha256: Option<&'a str>,
    response_body_sha256: &'a str,
    started_at: &'a str,
    finished_at: &'a str,
    bind: SocketAddr,
}

async fn serve_http(args: ServerServeArgs) -> BbxResult<()> {
    validate_ledger_path(&args.ledger)?;
    validate_http_bind(&args)?;
    validate_http_api_key_env_name(&args.api_key_env)?;
    let api_key = load_http_api_key(&args.api_key_env)?;
    let api_key_sha256 = sha256_hex(api_key.as_bytes());

    let conn = open_initialized_ledger(&args.ledger)?;
    verify_ledger_integrity(&conn, &args.ledger)?;
    drop(conn);

    let listener = tokio::net::TcpListener::bind(args.bind)
        .await
        .map_err(|err| {
            BlackboxError::new_with_connector(
                ErrorKind::Io,
                "HTTP_SERVER_BIND_FAILED",
                format!("failed to bind HTTP server to {}: {err}", args.bind),
                Some(format!("tcp:{}", args.bind)),
                HTTP_SERVER_CONNECTOR_ID,
                Some("--bind".to_string()),
                "choose an available loopback socket address or stop the process currently using that port",
            )
        })?;
    let local_addr = listener.local_addr().map_err(|err| {
        BlackboxError::new_with_connector(
            ErrorKind::Io,
            "HTTP_SERVER_BIND_INSPECT_FAILED",
            format!("failed to inspect bound HTTP server socket: {err}"),
            Some(format!("tcp:{}", args.bind)),
            HTTP_SERVER_CONNECTOR_ID,
            Some("--bind".to_string()),
            "inspect local socket permissions and retry",
        )
    })?;

    let state = HttpServerState {
        ledger: args.ledger.clone(),
        api_key_sha256,
        write_lock: Arc::new(tokio::sync::Mutex::new(())),
        bind: local_addr,
    };
    let app = http_router(state).layer(DefaultBodyLimit::max(HTTP_MAX_BODY_BYTES));
    eprintln!(
        "{}",
        serde_json::to_string_pretty(&json!({
            "status": "ok",
            "command": "blackbox server serve",
            "source_of_truth": source_of_truth(&args.ledger),
            "connector": HTTP_SERVER_CONNECTOR_ID,
            "bind": local_addr.to_string(),
            "protected_routes_require": ["Authorization: Bearer <api-key>", "X-Blackbox-Tenant"],
            "max_body_bytes": HTTP_MAX_BODY_BYTES,
            "audit_record_kind": "http_request_audit",
            "fail_closed": true,
        }))
        .expect("server startup JSON serializes")
    );

    axum::serve(listener, app).await.map_err(|err| {
        BlackboxError::new_with_connector(
            ErrorKind::Io,
            "HTTP_SERVER_RUNTIME_FAILED",
            format!("HTTP server stopped with an error: {err}"),
            Some(format!("tcp:{local_addr}")),
            HTTP_SERVER_CONNECTOR_ID,
            Some("axum::serve".to_string()),
            "inspect stderr logs and restart the server after fixing the socket/runtime failure",
        )
    })
}

fn http_router(state: HttpServerState) -> Router {
    Router::new()
        .route("/v1/health", get(http_health))
        .route("/v1/runs", post(http_record_run))
        .route("/v1/runs/{run_id}", get(http_get_run))
        .route("/v1/runs/{run_id}/steps", post(http_record_step))
        .route("/v1/tool-calls", post(http_record_tool_call))
        .route("/v1/dashboard/summary", get(http_dashboard_summary))
        .route("/v1/dashboard/runs", get(http_dashboard_runs))
        .route(
            "/v1/dashboard/runs/{run_id}/timeline",
            get(http_dashboard_timeline),
        )
        .route("/v1/dashboard/evidence", get(http_dashboard_evidence))
        .route(
            "/v1/dashboard/verifier-status",
            get(http_dashboard_verifiers),
        )
        .route("/v1/dashboard/errors", get(http_dashboard_errors))
        .route("/v1/dashboard/exports", get(http_dashboard_exports))
        .route(
            "/v1/dashboard/pilot-packages",
            get(http_dashboard_pilot_packages),
        )
        .route(
            "/v1/dashboard/risk-assessments",
            get(http_dashboard_risk_assessments),
        )
        .with_state(state)
}

async fn http_health(State(state): State<HttpServerState>) -> Response {
    let request_id = prefixed_id("http_req");
    let started_at = Utc::now().to_rfc3339();
    let result = (|| -> BbxResult<Value> {
        let conn = open_initialized_ledger(&state.ledger)?;
        let inspection = verify_ledger_integrity(&conn, &state.ledger)?;
        Ok(json!({
            "status": "ok",
            "request_id": request_id,
            "connector": HTTP_SERVER_CONNECTOR_ID,
            "source_of_truth": source_of_truth(&state.ledger),
            "schema_version": LEDGER_SCHEMA_VERSION,
            "record_count": inspection.record_count,
            "ledger_tip_sha256": inspection.ledger_tip_sha256,
            "started_at": started_at,
        }))
    })();
    match result {
        Ok(value) => http_json_response(StatusCode::OK, value),
        Err(err) => http_error_response(http_status_for_error(&err), &request_id, err, None, None),
    }
}

async fn http_record_run(
    State(state): State<HttpServerState>,
    headers: AxumHeaderMap,
    body: Result<Bytes, BytesRejection>,
) -> Response {
    let route_id = "POST /v1/runs";
    let path = "/v1/runs";
    let method = "POST";
    let started_at = Utc::now().to_rfc3339();
    let request_id = http_request_id(&headers);
    let result = async {
        let (ctx, request, body_hash) = parse_authenticated_json::<HttpRecordRunRequest>(
            &state,
            &headers,
            body,
            path,
            &request_id,
        )?;
        require_body_tenant_matches_header(
            &state.ledger,
            &ctx.tenant,
            &request.tenant,
            "$.tenant",
        )?;
        let _guard = state.write_lock.lock().await;
        let output = record_run_from_parts(
            &state.ledger,
            &request.task,
            &request.agent,
            &request.tenant,
            request.model.as_deref(),
            &request.task_kind,
            &request.risk_tier,
            "http_server",
        )?;
        append_success_audit(
            &state,
            &ctx,
            method,
            path,
            route_id,
            Some(&body_hash),
            &started_at,
            &output,
        )?;
        Ok::<Value, BlackboxError>(output)
    }
    .await;
    http_finish_response(
        &state,
        route_id,
        method,
        path,
        &request_id,
        &started_at,
        result,
    )
    .await
}

